// 2019～2022年度相当のオリジナル学習問題。公式問題本文の転載ではありません。
window.SKIMARU_EXTRA_QUESTIONS = [{"id":1001,"year":2019,"category":"生産の基本","text":"5Sは、整理・整頓・清掃・清潔・しつけの5項目で構成される。","answer":true,"explanation":"5Sは整理・整頓・清掃・清潔・しつけです。"},{"id":1002,"year":2019,"category":"生産の基本","text":"整理とは、必要な物を使いやすい場所へ並べる活動だけを指す。","answer":false,"explanation":"不要品を区分して処分するのが整理で、置き場所や置き方を決めるのは整頓です。"},{"id":1003,"year":2019,"category":"生産の基本","text":"整頓では、定位置・定品・定量を決める3定が有効である。","answer":true,"explanation":"整頓では誰でも分かる置き場所・品目・量を定めることが重要です。"},{"id":1004,"year":2019,"category":"生産の基本","text":"QCDのDは、Designを表す。","answer":false,"explanation":"QCDのDはDelivery（納期）です。"},{"id":1005,"year":2019,"category":"生産の基本","text":"PDCAのCheckでは、実施結果を評価し計画との差を確認する。","answer":true,"explanation":"Checkは結果の確認・評価、Planは計画です。"},{"id":1006,"year":2019,"category":"生産の基本","text":"三現主義は、現場・現金・現役を重視する考え方である。","answer":false,"explanation":"問題解決では現場へ行き、現物を見て、現実を確認します。"},{"id":1007,"year":2019,"category":"生産の基本","text":"KY活動は、作業前に潜在する危険を予測し、安全行動を決める活動である。","answer":true,"explanation":"KYは危険予知であり、災害を未然に防ぐために行います。"},{"id":1008,"year":2019,"category":"生産の基本","text":"ヒヤリ・ハットは災害ではないため、記録や共有を行う必要はない。","answer":false,"explanation":"軽微な兆候を共有して危険源を早期に除去することが重要です。"},{"id":1009,"year":2019,"category":"生産の基本","text":"標準作業は、安全・品質・能率を考慮して定めた手順を守ることが基本である。","answer":true,"explanation":"標準作業はばらつきを抑え、安全・品質・生産性を安定させます。"},{"id":1010,"year":2019,"category":"生産の基本","text":"OJTは、職場を離れて集合研修だけで学ぶ教育方法である。","answer":false,"explanation":"仕事を通じた教育がOJT、職場を離れた教育はOff-JTです。"},{"id":1011,"year":2019,"category":"生産の基本","text":"Off-JTは、通常業務を離れて研修などで学ぶ教育方法である。","answer":true,"explanation":"Off-JTは職場業務を離れて行う研修・講習などです。"},{"id":1012,"year":2019,"category":"生産の基本","text":"リスクアセスメントは、生産数量を増やすことだけを目的とする。","answer":false,"explanation":"危険源を特定し、リスク低減措置を検討する安全管理手法です。"},{"id":1013,"year":2019,"category":"生産の基本","text":"フェイルセーフは、機器が故障しても危険側へ移行しにくくする考え方である。","answer":true,"explanation":"故障時に安全側へ移行する設計思想がフェイルセーフです。"},{"id":1014,"year":2019,"category":"生産の基本","text":"フールプルーフは、熟練者だけが操作できるよう手順を複雑にする考え方である。","answer":false,"explanation":"人がミスしても危険や不良につながりにくい仕組みにします。"},{"id":1015,"year":2019,"category":"生産の基本","text":"酸素濃度18％未満は、酸素欠乏状態として扱われる。","answer":true,"explanation":"酸素欠乏症等防止規則では18％未満を酸素欠乏とします。"},{"id":1016,"year":2019,"category":"生産の基本","text":"保護具は設備停止中だけ使用し、運転中は着用しないのが原則である。","answer":false,"explanation":"危険源に応じて適切な保護具を選び、定められた方法で着用します。"},{"id":1017,"year":2019,"category":"生産の基本","text":"抜取り検査は、ロットの一部を抽出して合否判定に用いる検査である。","answer":true,"explanation":"全数を検査するのは全数検査、ロットの一部を調べるのが抜取り検査です。"},{"id":1018,"year":2019,"category":"生産の基本","text":"環境管理の3Rは、Repair・Return・Recordである。","answer":false,"explanation":"3Rは発生抑制・再使用・再生利用です。"},{"id":1019,"year":2019,"category":"生産の基本","text":"典型7公害には、大気汚染・水質汚濁・騒音などが含まれる。","answer":true,"explanation":"典型7公害は環境基本法上の公害類型です。"},{"id":1020,"year":2019,"category":"生産の基本","text":"5W1Hの5つのWには、Watch・Write・Work・Wash・Waitが含まれる。","answer":false,"explanation":"5W1Hは誰が、何を、いつ、どこで、なぜ、どのように、で整理します。"},{"id":1021,"year":2019,"category":"設備の日常保全","text":"自主保全の基本条件には、清掃・給油・増し締めが含まれる。","answer":true,"explanation":"清掃・給油・増し締めは設備の基本条件を整える代表的な活動です。"},{"id":1022,"year":2019,"category":"設備の日常保全","text":"清掃は外観をきれいにするだけで、点検とは無関係である。","answer":false,"explanation":"清掃を通じて漏れ、ゆるみ、摩耗、異音などを発見します。"},{"id":1023,"year":2019,"category":"設備の日常保全","text":"初期清掃では、汚れを除去しながら不具合や不要物を発見する。","answer":true,"explanation":"自主保全の初期段階では清掃を通じて設備の実態を把握します。"},{"id":1024,"year":2019,"category":"設備の日常保全","text":"発生源対策では、汚れの発生量を増やして清掃回数を多くする。","answer":false,"explanation":"清掃だけでなく、汚れを出さない・飛散させない改善が重要です。"},{"id":1025,"year":2019,"category":"設備の日常保全","text":"困難箇所対策では、清掃・点検・給油を短時間かつ安全に行えるよう改善する。","answer":true,"explanation":"点検窓、給油口の集約、カバー改善などで保全性を高めます。"},{"id":1026,"year":2019,"category":"設備の日常保全","text":"暫定基準は、生産数量だけを定める表であり点検内容は含まれない。","answer":false,"explanation":"自主保全基準には対象、方法、周期、判定基準などを明確にします。"},{"id":1027,"year":2019,"category":"設備の日常保全","text":"強制劣化は、清掃・給油・増し締め不足などにより本来防げる劣化が進むことである。","answer":true,"explanation":"基本条件の不備による人為的な劣化を強制劣化と呼びます。"},{"id":1028,"year":2019,"category":"設備の日常保全","text":"自然劣化は、締付不足や給油忘れだけによって発生する。","answer":false,"explanation":"時間経過による腐食や老化などが自然劣化です。"},{"id":1029,"year":2019,"category":"設備の日常保全","text":"指定と異なる潤滑油を安易に混用すると、性能低下を招く場合がある。","answer":true,"explanation":"油種や添加剤の相性で性能が低下することがあるため、指定油を守ります。"},{"id":1030,"year":2019,"category":"設備の日常保全","text":"潤滑の主目的は、摩擦を増やして機械を停止させることである。","answer":false,"explanation":"潤滑は摩擦・摩耗低減、冷却、防錆、密封などに寄与します。"},{"id":1031,"year":2019,"category":"設備の日常保全","text":"グリースは、基油に増ちょう剤などを加えた半固体状の潤滑剤である。","answer":true,"explanation":"グリースは基油を増ちょう剤で保持した潤滑剤です。"},{"id":1032,"year":2019,"category":"設備の日常保全","text":"油面計が汚れて読めなくても、給油してあれば管理上問題ない。","answer":false,"explanation":"油量を見える化し、正常・異常を容易に判定できる状態が必要です。"},{"id":1033,"year":2019,"category":"設備の日常保全","text":"日常点検では、運転中の音・振動・温度・漏れなどを確認することがある。","answer":true,"explanation":"日常点検は五感や簡易計器による状態確認が中心です。"},{"id":1034,"year":2019,"category":"設備の日常保全","text":"ボルトの合いマークは、締結トルクを自動で増加させる装置である。","answer":false,"explanation":"マークのずれにより、ゆるみの兆候を視覚的に確認できます。"},{"id":1035,"year":2019,"category":"設備の日常保全","text":"締結部のゆるみは、振動増大や部品脱落の原因になることがある。","answer":true,"explanation":"ゆるみは振動、騒音、位置ずれ、脱落などにつながります。"},{"id":1036,"year":2019,"category":"設備の日常保全","text":"空気圧設備のフィルタやドレンは、設備寿命に影響しないため点検不要である。","answer":false,"explanation":"異物や水分は機器の作動不良や腐食につながるため管理が必要です。"},{"id":1037,"year":2019,"category":"設備の日常保全","text":"点検箇所の集中化や見える化は、点検時間短縮と見落とし防止に役立つ。","answer":true,"explanation":"アクセス性を高め、正常・異常を判定しやすくする改善が有効です。"},{"id":1038,"year":2019,"category":"設備の日常保全","text":"不具合札は、異常箇所を隠して他の作業者に知らせないために使う。","answer":false,"explanation":"不具合の発見・処置・完了を見える化して管理します。"},{"id":1039,"year":2019,"category":"設備の日常保全","text":"自主保全では、発見した微欠陥を放置せず、復元または改善につなげる。","answer":true,"explanation":"小さな異常を早期に処置することが故障の未然防止につながります。"},{"id":1040,"year":2019,"category":"設備の日常保全","text":"自主保全では、正常・異常の判断基準を個人の勘だけに任せることが望ましい。","answer":false,"explanation":"定量的な判定基準を決め、誰でも同じ判断ができるようにします。"},{"id":1041,"year":2019,"category":"効率化とロス","text":"設備総合効率は、時間稼働率・性能稼働率・良品率の積で表される。","answer":true,"explanation":"OEEは時間稼働率×性能稼働率×良品率で求めます。"},{"id":1042,"year":2019,"category":"効率化とロス","text":"故障による停止時間が増えるほど、時間稼働率は高くなる。","answer":false,"explanation":"稼働時間が減るため時間稼働率は低下します。"},{"id":1043,"year":2019,"category":"効率化とロス","text":"チョコ停や速度低下は、性能稼働率に影響する。","answer":true,"explanation":"小停止や速度低下は設備の本来性能を発揮できないロスです。"},{"id":1044,"year":2019,"category":"効率化とロス","text":"不良品が増えるほど、良品率は必ず上昇する。","answer":false,"explanation":"投入数に対する良品数の割合が低下します。"},{"id":1045,"year":2019,"category":"効率化とロス","text":"故障ロスは、設備効率を阻害する代表的なロスの一つである。","answer":true,"explanation":"故障停止は設備の有効稼働時間を減らす大きなロスです。"},{"id":1046,"year":2019,"category":"効率化とロス","text":"段取り時間を長くするほど、時間稼働率が向上する。","answer":false,"explanation":"段取り短縮は停止時間を減らし、稼働時間を増やします。"},{"id":1047,"year":2019,"category":"効率化とロス","text":"チョコ停は、短時間の一時停止や空転が繰り返される現象を指す。","answer":true,"explanation":"短時間でも頻発すると大きな性能ロスになります。"},{"id":1048,"year":2019,"category":"効率化とロス","text":"基準速度より速く運転すれば、どのような場合も速度低下ロスが発生する。","answer":false,"explanation":"本来出せる速度に対して実際の速度が低い差がロスです。"},{"id":1049,"year":2019,"category":"効率化とロス","text":"立上りロスは、始業時や条件変更後に安定生産へ移るまでに生じる。","answer":true,"explanation":"条件安定までの時間や不良発生などを立上りロスとして捉えます。"},{"id":1050,"year":2019,"category":"効率化とロス","text":"機能停止型故障では、設備は常に本来性能を100％維持している。","answer":false,"explanation":"機能が停止する故障と、性能が低下する機能低下型故障があります。"},{"id":1051,"year":2019,"category":"効率化とロス","text":"予防保全は、故障を未然に防ぐため計画的に保全する考え方である。","answer":true,"explanation":"故障前に点検・交換などを行うのが予防保全です。"},{"id":1052,"year":2019,"category":"効率化とロス","text":"事後保全は、設備状態を常時監視して故障前に部品交換する方式だけを指す。","answer":false,"explanation":"故障発生後に処置する保全を事後保全と呼びます。"},{"id":1053,"year":2019,"category":"効率化とロス","text":"TBMは、時間や使用回数など一定の周期を基準に行う保全である。","answer":true,"explanation":"時間基準保全は周期・時間を基準にします。"},{"id":1054,"year":2019,"category":"効率化とロス","text":"CBMは、設備状態に関係なく必ず同じ日付に部品交換する方式である。","answer":false,"explanation":"状態基準保全は状態監視結果に基づいて保全します。"},{"id":1055,"year":2019,"category":"効率化とロス","text":"改良保全（CM）は、故障しにくく保全しやすい設備へ改善する活動である。","answer":true,"explanation":"弱点を改善して信頼性・保全性を向上させる考え方です。"},{"id":1056,"year":2019,"category":"効率化とロス","text":"保全予防（MP）は、設備導入後に故障してから設計を考える活動だけを指す。","answer":false,"explanation":"MPは保全情報を新設備の計画・設計へ反映します。"},{"id":1057,"year":2019,"category":"効率化とロス","text":"TPMは、トップから第一線まで全員参加でロスゼロを目指す活動である。","answer":true,"explanation":"TPMは全部門・全員参加が基本です。"},{"id":1058,"year":2019,"category":"効率化とロス","text":"ロスは数値化せず感覚だけで判断する方が、重点課題を選びやすい。","answer":false,"explanation":"定量化により重点指向で改善できます。"},{"id":1059,"year":2019,"category":"効率化とロス","text":"設備だけでなく、人や材料・エネルギーに関するロスも改善対象となる。","answer":true,"explanation":"生産システム全体のロスを捉えることが重要です。"},{"id":1060,"year":2019,"category":"効率化とロス","text":"良品率は、不良数を良品数で割った値だけを指す。","answer":false,"explanation":"一般に良品数÷投入数で評価します。"},{"id":1061,"year":2019,"category":"改善・解析","text":"パレート図は、項目を大きい順に並べて重点課題を見つけるのに有効である。","answer":true,"explanation":"パレート図は重要な少数を見つけ、改善の優先順位を決めるのに使います。"},{"id":1062,"year":2019,"category":"改善・解析","text":"特性要因図は、時系列データの管理限界だけを監視する図である。","answer":false,"explanation":"魚の骨状に要因を整理し、原因探索に活用します。"},{"id":1063,"year":2019,"category":"改善・解析","text":"ヒストグラムは、データの分布やばらつきを把握するのに使う。","answer":true,"explanation":"区間ごとの度数を棒で表し、分布の形やばらつきを見ます。"},{"id":1064,"year":2019,"category":"改善・解析","text":"散布図は、不良項目を大きい順に並べるためだけの図である。","answer":false,"explanation":"対応する2変数を点で表し、関係性を確認します。"},{"id":1065,"year":2019,"category":"改善・解析","text":"チェックシートは、データを決めた形式で簡単に記録・集計するために使う。","answer":true,"explanation":"現場でデータを取りやすく、集計しやすくする基本ツールです。"},{"id":1066,"year":2019,"category":"改善・解析","text":"管理図の管理限界線は、顧客仕様の上限・下限と常に同じ値である。","answer":false,"explanation":"管理限界は工程データから設定され、仕様限界とは目的が異なります。"},{"id":1067,"year":2019,"category":"改善・解析","text":"層別は、機械別・人別・材料別などにデータを分けて特徴を調べる考え方である。","answer":true,"explanation":"条件ごとに分けることで問題の偏りを見つけやすくなります。"},{"id":1068,"year":2019,"category":"改善・解析","text":"4Mは、Money・Market・Month・Memoの4項目を指す。","answer":false,"explanation":"4Mは人・設備・材料・方法の視点です。"},{"id":1069,"year":2019,"category":"改善・解析","text":"なぜなぜ分析では、現象に対して「なぜ」を繰り返して真因へ近づく。","answer":true,"explanation":"事実を確認しながら因果関係を掘り下げます。"},{"id":1070,"year":2019,"category":"改善・解析","text":"QCストーリーでは、原因を調べる前に対策を固定し、効果確認は行わない。","answer":false,"explanation":"問題解決を一定の手順で進め、効果を確認して標準化します。"},{"id":1071,"year":2019,"category":"改善・解析","text":"ECRSのEはEliminateで、不要な作業をなくせないか検討する。","answer":true,"explanation":"ECRSは排除・結合・交換・簡素化の観点です。"},{"id":1072,"year":2019,"category":"改善・解析","text":"ECRSのCはCancelで、設備を停止することだけを意味する。","answer":false,"explanation":"Combineは作業や工程の結合です。"},{"id":1073,"year":2019,"category":"改善・解析","text":"作業改善では、不要な移動や探す時間を減らすことも改善対象となる。","answer":true,"explanation":"動作・運搬・待ちなどのムダを減らすことが重要です。"},{"id":1074,"year":2019,"category":"改善・解析","text":"改善後は、効果確認をせず対策を成功と判断するのが原則である。","answer":false,"explanation":"データで効果を検証し、必要なら追加対策を行います。"},{"id":1075,"year":2019,"category":"改善・解析","text":"効果が確認できた改善は、標準化して良い状態を維持することが重要である。","answer":true,"explanation":"再発防止と横展開には標準化が重要です。"},{"id":1076,"year":2019,"category":"改善・解析","text":"問題解析では、原因を確認せず推測だけで対策する方が再発防止に有効である。","answer":false,"explanation":"現地現物とデータに基づいて真因を特定します。"},{"id":1077,"year":2019,"category":"改善・解析","text":"管理値を設定すると、正常・異常の判定を定量化しやすい。","answer":true,"explanation":"定量基準により判断のばらつきを減らせます。"},{"id":1078,"year":2019,"category":"改善・解析","text":"再発防止では、原因を残したまま応急処置だけを繰り返すことが最適である。","answer":false,"explanation":"応急処置と恒久対策を区別し、真因へ対策します。"},{"id":1079,"year":2019,"category":"改善・解析","text":"改善テーマは、ロスの大きさや緊急度などを基に優先順位を決めるとよい。","answer":true,"explanation":"重点指向でテーマを選定すると改善効果を高めやすくなります。"},{"id":1080,"year":2019,"category":"改善・解析","text":"測定条件や単位が異なっていても、そのまま比較して問題ない。","answer":false,"explanation":"条件や単位をそろえないと正しい比較ができません。"},{"id":1081,"year":2019,"category":"設備保全の基礎","text":"転がり軸受は、転動体を介して軸を支持する軸受である。","answer":true,"explanation":"玉やころなどの転動体を用いるのが転がり軸受です。"},{"id":1082,"year":2019,"category":"設備保全の基礎","text":"Vベルトは、歯車のかみ合いだけで動力を伝達する。","answer":false,"explanation":"Vベルトはプーリーとの摩擦を利用する伝動要素です。"},{"id":1083,"year":2019,"category":"設備保全の基礎","text":"チェーン伝動では、張り過ぎだけでなく適正なたるみや給油状態も確認する。","answer":true,"explanation":"過大張力も過大なたるみも異常の原因になります。"},{"id":1084,"year":2019,"category":"設備保全の基礎","text":"歯車の歯が欠けても、回転状態や振動には影響しない。","answer":false,"explanation":"歯面損傷はかみ合い異常を生み、振動・騒音につながります。"},{"id":1085,"year":2019,"category":"設備保全の基礎","text":"メカニカルシールは、回転軸周りの流体漏れを抑える密封装置の一つである。","answer":true,"explanation":"回転機器の軸封に使われる代表的な密封装置です。"},{"id":1086,"year":2019,"category":"設備保全の基礎","text":"レギュレーターは、圧縮空気中の油分を完全燃焼させる機器である。","answer":false,"explanation":"レギュレーターは減圧・圧力調整に使います。"},{"id":1087,"year":2019,"category":"設備保全の基礎","text":"エアフィルターは、圧縮空気中の異物や水分を除去するために用いる。","answer":true,"explanation":"異物やドレンの除去に用います。"},{"id":1088,"year":2019,"category":"設備保全の基礎","text":"空気圧シリンダーは、交流電圧を直流へ変換する機器である。","answer":false,"explanation":"圧縮空気を利用してロッドを直線運動させます。"},{"id":1089,"year":2019,"category":"設備保全の基礎","text":"油圧シリンダーは、油圧エネルギーを直線往復運動に変換する。","answer":true,"explanation":"油圧アクチュエーターとして直線運動を発生させます。"},{"id":1090,"year":2019,"category":"設備保全の基礎","text":"パスカルの原理では、密閉流体に加えた圧力は一方向にしか伝わらない。","answer":false,"explanation":"密閉流体の圧力は各方向へ等しく伝わります。"},{"id":1091,"year":2019,"category":"設備保全の基礎","text":"電磁弁は、電気信号によって流体の流れ方向などを切り替えるために使われる。","answer":true,"explanation":"ソレノイドを用いて流路を切り替える弁です。"},{"id":1092,"year":2019,"category":"設備保全の基礎","text":"リミットスイッチは、主に液体のpHを非接触で測定するセンサーである。","answer":false,"explanation":"レバーやローラーへの接触で位置を検出します。"},{"id":1093,"year":2019,"category":"設備保全の基礎","text":"近接センサーは、対象物に接触せず検出できる種類がある。","answer":true,"explanation":"誘導形などは金属を非接触で検出できます。"},{"id":1094,"year":2019,"category":"設備保全の基礎","text":"光電センサーは、圧縮空気の圧力だけを測定する機器である。","answer":false,"explanation":"投光・受光の変化で対象物を検出します。"},{"id":1095,"year":2019,"category":"設備保全の基礎","text":"オームの法則では、電流は電圧を抵抗で割って求められる。","answer":true,"explanation":"I=V/Rです。"},{"id":1096,"year":2019,"category":"設備保全の基礎","text":"テスターで抵抗を測定するときは、必ず通電中の回路へ接続する。","answer":false,"explanation":"抵抗測定は電源を切り、安全を確認して行います。"},{"id":1097,"year":2019,"category":"設備保全の基礎","text":"インバーターは、モーターへ供給する周波数などを制御して回転速度を調整できる。","answer":true,"explanation":"周波数・電圧制御によりモーター速度を調整します。"},{"id":1098,"year":2019,"category":"設備保全の基礎","text":"ノギスは、電圧・電流・抵抗を測定する電気計器である。","answer":false,"explanation":"ノギスは寸法測定に使用する測定器です。"},{"id":1099,"year":2019,"category":"設備保全の基礎","text":"マイクロメータは、一般にノギスより細かい寸法を読み取れる。","answer":true,"explanation":"マイクロメータは高精度な寸法測定に用います。"},{"id":1100,"year":2019,"category":"設備保全の基礎","text":"寸法公差は、図面寸法と実測値の差だけを指す。","answer":false,"explanation":"許容される寸法範囲の幅が寸法公差です。"},{"id":1101,"year":2020,"category":"生産の基本","text":"現場での基本事項として、5Sは、整理・整頓・清掃・修理・しつけの5項目で構成される。","answer":false,"explanation":"5Sは整理・整頓・清掃・清潔・しつけです。"},{"id":1102,"year":2020,"category":"生産の基本","text":"現場での基本事項として、整理とは、必要な物と不要な物を分け、不要な物を処分する活動である。","answer":true,"explanation":"不要品を区分して処分するのが整理で、置き場所や置き方を決めるのは整頓です。"},{"id":1103,"year":2020,"category":"生産の基本","text":"現場での基本事項として、整頓では、置き場所を決めず、作業者ごとに使いやすい位置へ置くのが基本である。","answer":false,"explanation":"整頓では誰でも分かる置き場所・品目・量を定めることが重要です。"},{"id":1104,"year":2020,"category":"生産の基本","text":"現場での基本事項として、QCDは、Quality・Cost・Deliveryを表す。","answer":true,"explanation":"QCDのDはDelivery（納期）です。"},{"id":1105,"year":2020,"category":"生産の基本","text":"現場での基本事項として、PDCAのCheckでは、新しい計画を立てることだけを行う。","answer":false,"explanation":"Checkは結果の確認・評価、Planは計画です。"},{"id":1106,"year":2020,"category":"生産の基本","text":"現場での基本事項として、三現主義は、現場・現物・現実を重視する考え方である。","answer":true,"explanation":"問題解決では現場へ行き、現物を見て、現実を確認します。"},{"id":1107,"year":2020,"category":"生産の基本","text":"現場での基本事項として、KY活動は、災害発生後に責任者を決めることを目的とする活動である。","answer":false,"explanation":"KYは危険予知であり、災害を未然に防ぐために行います。"},{"id":1108,"year":2020,"category":"生産の基本","text":"現場での基本事項として、ヒヤリ・ハット事例の共有は、重大災害の未然防止に役立つ。","answer":true,"explanation":"軽微な兆候を共有して危険源を早期に除去することが重要です。"},{"id":1109,"year":2020,"category":"生産の基本","text":"現場での基本事項として、標準作業は、作業者が毎回自由に手順を変更することを前提とする。","answer":false,"explanation":"標準作業はばらつきを抑え、安全・品質・生産性を安定させます。"},{"id":1110,"year":2020,"category":"生産の基本","text":"現場での基本事項として、OJTは、実際の仕事を通じて知識や技能を身につける教育方法である。","answer":true,"explanation":"仕事を通じた教育がOJT、職場を離れた教育はOff-JTです。"},{"id":1111,"year":2020,"category":"生産の基本","text":"現場での基本事項として、Off-JTは、必ず実機を運転しながら行う教育方法である。","answer":false,"explanation":"Off-JTは職場業務を離れて行う研修・講習などです。"},{"id":1112,"year":2020,"category":"生産の基本","text":"現場での基本事項として、リスクアセスメントでは、危険性・有害性を特定し、リスクを見積もって低減する。","answer":true,"explanation":"危険源を特定し、リスク低減措置を検討する安全管理手法です。"},{"id":1113,"year":2020,"category":"生産の基本","text":"現場での基本事項として、フェイルセーフは、故障時に設備を最高速度で運転継続させる考え方である。","answer":false,"explanation":"故障時に安全側へ移行する設計思想がフェイルセーフです。"},{"id":1114,"year":2020,"category":"生産の基本","text":"現場での基本事項として、フールプルーフは、誤操作しても事故や不良につながりにくくする工夫である。","answer":true,"explanation":"人がミスしても危険や不良につながりにくい仕組みにします。"},{"id":1115,"year":2020,"category":"生産の基本","text":"現場での基本事項として、酸素濃度20％は、必ず酸素欠乏状態である。","answer":false,"explanation":"酸素欠乏症等防止規則では18％未満を酸素欠乏とします。"},{"id":1116,"year":2020,"category":"生産の基本","text":"現場での基本事項として、保護メガネや耳栓などの保護具は、対象となる危険に応じて適切に使用する。","answer":true,"explanation":"危険源に応じて適切な保護具を選び、定められた方法で着用します。"},{"id":1117,"year":2020,"category":"生産の基本","text":"現場での基本事項として、抜取り検査とは、生産した製品をすべて1個ずつ検査することである。","answer":false,"explanation":"全数を検査するのは全数検査、ロットの一部を調べるのが抜取り検査です。"},{"id":1118,"year":2020,"category":"生産の基本","text":"現場での基本事項として、環境管理の3Rは、Reduce・Reuse・Recycleである。","answer":true,"explanation":"3Rは発生抑制・再使用・再生利用です。"},{"id":1119,"year":2020,"category":"生産の基本","text":"現場での基本事項として、典型7公害には、納期遅延や在庫過多が含まれる。","answer":false,"explanation":"典型7公害は環境基本法上の公害類型です。"},{"id":1120,"year":2020,"category":"生産の基本","text":"現場での基本事項として、5W1Hは、Who・What・When・Where・Why・Howで整理する方法である。","answer":true,"explanation":"5W1Hは誰が、何を、いつ、どこで、なぜ、どのように、で整理します。"},{"id":1121,"year":2020,"category":"設備の日常保全","text":"現場での基本事項として、自主保全の基本条件は、塗装・溶接・機械加工の3項目だけである。","answer":false,"explanation":"清掃・給油・増し締めは設備の基本条件を整える代表的な活動です。"},{"id":1122,"year":2020,"category":"設備の日常保全","text":"現場での基本事項として、「清掃は点検なり」とは、清掃中に微欠陥や異常を発見することを重視する考え方である。","answer":true,"explanation":"清掃を通じて漏れ、ゆるみ、摩耗、異音などを発見します。"},{"id":1123,"year":2020,"category":"設備の日常保全","text":"現場での基本事項として、初期清掃では、設備を清掃せずに点検基準書だけを作成する。","answer":false,"explanation":"自主保全の初期段階では清掃を通じて設備の実態を把握します。"},{"id":1124,"year":2020,"category":"設備の日常保全","text":"現場での基本事項として、発生源対策では、汚れの発生そのものを減らすことを優先する。","answer":true,"explanation":"清掃だけでなく、汚れを出さない・飛散させない改善が重要です。"},{"id":1125,"year":2020,"category":"設備の日常保全","text":"現場での基本事項として、困難箇所対策では、点検口を減らして設備内部を見えなくする。","answer":false,"explanation":"点検窓、給油口の集約、カバー改善などで保全性を高めます。"},{"id":1126,"year":2020,"category":"設備の日常保全","text":"現場での基本事項として、暫定基準には、清掃・給油・点検の箇所や周期などを定める。","answer":true,"explanation":"自主保全基準には対象、方法、周期、判定基準などを明確にします。"},{"id":1127,"year":2020,"category":"設備の日常保全","text":"現場での基本事項として、強制劣化は、設備を正しく管理していても必ず同じ速度で進む自然現象だけを指す。","answer":false,"explanation":"基本条件の不備による人為的な劣化を強制劣化と呼びます。"},{"id":1128,"year":2020,"category":"設備の日常保全","text":"現場での基本事項として、自然劣化には、経年による腐食や材料の老化などが含まれる。","answer":true,"explanation":"時間経過による腐食や老化などが自然劣化です。"},{"id":1129,"year":2020,"category":"設備の日常保全","text":"現場での基本事項として、粘度が同じなら、油種や添加剤が異なっても必ず混ぜて使用できる。","answer":false,"explanation":"油種や添加剤の相性で性能が低下することがあるため、指定油を守ります。"},{"id":1130,"year":2020,"category":"設備の日常保全","text":"現場での基本事項として、潤滑には、摩擦・摩耗の低減や冷却などの役割がある。","answer":true,"explanation":"潤滑は摩擦・摩耗低減、冷却、防錆、密封などに寄与します。"},{"id":1131,"year":2020,"category":"設備の日常保全","text":"現場での基本事項として、グリースは、潤滑成分を含まない乾燥した粉末だけで構成される。","answer":false,"explanation":"グリースは基油を増ちょう剤で保持した潤滑剤です。"},{"id":1132,"year":2020,"category":"設備の日常保全","text":"現場での基本事項として、油面計は、油量を正しく確認できるよう清潔で見やすい状態に保つ。","answer":true,"explanation":"油量を見える化し、正常・異常を容易に判定できる状態が必要です。"},{"id":1133,"year":2020,"category":"設備の日常保全","text":"現場での基本事項として、日常点検では、設備の運転状態を確認せず、必ず全分解して点検する。","answer":false,"explanation":"日常点検は五感や簡易計器による状態確認が中心です。"},{"id":1134,"year":2020,"category":"設備の日常保全","text":"現場での基本事項として、ボルトの合いマークは、締結部のゆるみを目視で発見しやすくする。","answer":true,"explanation":"マークのずれにより、ゆるみの兆候を視覚的に確認できます。"},{"id":1135,"year":2020,"category":"設備の日常保全","text":"現場での基本事項として、締結部がゆるむほど、振動は必ず減少し安全性が向上する。","answer":false,"explanation":"ゆるみは振動、騒音、位置ずれ、脱落などにつながります。"},{"id":1136,"year":2020,"category":"設備の日常保全","text":"現場での基本事項として、空気圧設備では、フィルタの汚れやドレンの滞留も日常点検の対象となる。","answer":true,"explanation":"異物や水分は機器の作動不良や腐食につながるため管理が必要です。"},{"id":1137,"year":2020,"category":"設備の日常保全","text":"現場での基本事項として、点検箇所を設備の裏側へ分散させるほど、点検は短時間で確実になる。","answer":false,"explanation":"アクセス性を高め、正常・異常を判定しやすくする改善が有効です。"},{"id":1138,"year":2020,"category":"設備の日常保全","text":"現場での基本事項として、不具合札（エフ）は、発見した異常箇所と処置状況を見える化するために使う。","answer":true,"explanation":"不具合の発見・処置・完了を見える化して管理します。"},{"id":1139,"year":2020,"category":"設備の日常保全","text":"現場での基本事項として、微欠陥は故障していない限り、記録せず放置するのが原則である。","answer":false,"explanation":"小さな異常を早期に処置することが故障の未然防止につながります。"},{"id":1140,"year":2020,"category":"設備の日常保全","text":"現場での基本事項として、オペレーターには、正常と異常を判断するための条件設定能力が求められる。","answer":true,"explanation":"定量的な判定基準を決め、誰でも同じ判断ができるようにします。"},{"id":1141,"year":2020,"category":"効率化とロス","text":"現場での基本事項として、設備総合効率は、時間稼働率と不良率を単純に足して求める。","answer":false,"explanation":"OEEは時間稼働率×性能稼働率×良品率で求めます。"},{"id":1142,"year":2020,"category":"効率化とロス","text":"現場での基本事項として、故障や段取りによる停止時間は、時間稼働率を低下させる。","answer":true,"explanation":"稼働時間が減るため時間稼働率は低下します。"},{"id":1143,"year":2020,"category":"効率化とロス","text":"現場での基本事項として、チョコ停や速度低下は、良品率だけに影響し性能稼働率には関係しない。","answer":false,"explanation":"小停止や速度低下は設備の本来性能を発揮できないロスです。"},{"id":1144,"year":2020,"category":"効率化とロス","text":"現場での基本事項として、不良・手直しが増えると、良品率が低下する。","answer":true,"explanation":"投入数に対する良品数の割合が低下します。"},{"id":1145,"year":2020,"category":"効率化とロス","text":"現場での基本事項として、故障ロスは、生産効率には影響しないためロスとして扱わない。","answer":false,"explanation":"故障停止は設備の有効稼働時間を減らす大きなロスです。"},{"id":1146,"year":2020,"category":"効率化とロス","text":"現場での基本事項として、段取り・調整時間の短縮は、停止ロス低減に有効である。","answer":true,"explanation":"段取り短縮は停止時間を減らし、稼働時間を増やします。"},{"id":1147,"year":2020,"category":"効率化とロス","text":"現場での基本事項として、チョコ停とは、数日間にわたる大規模故障だけを指す。","answer":false,"explanation":"短時間でも頻発すると大きな性能ロスになります。"},{"id":1148,"year":2020,"category":"効率化とロス","text":"現場での基本事項として、速度低下ロスは、基準速度より遅く運転することで生じる。","answer":true,"explanation":"本来出せる速度に対して実際の速度が低い差がロスです。"},{"id":1149,"year":2020,"category":"効率化とロス","text":"現場での基本事項として、立上りロスは、設備停止後の廃棄物処理だけを指す。","answer":false,"explanation":"条件安定までの時間や不良発生などを立上りロスとして捉えます。"},{"id":1150,"year":2020,"category":"効率化とロス","text":"現場での基本事項として、機能停止型故障は、設備が本来の機能を完全に果たせなくなる故障である。","answer":true,"explanation":"機能が停止する故障と、性能が低下する機能低下型故障があります。"},{"id":1151,"year":2020,"category":"効率化とロス","text":"現場での基本事項として、予防保全は、故障後にだけ修理する事後保全と同じ意味である。","answer":false,"explanation":"故障前に点検・交換などを行うのが予防保全です。"},{"id":1152,"year":2020,"category":"効率化とロス","text":"現場での基本事項として、事後保全は、故障が発生してから修理・復旧する保全方式である。","answer":true,"explanation":"故障発生後に処置する保全を事後保全と呼びます。"},{"id":1153,"year":2020,"category":"効率化とロス","text":"現場での基本事項として、TBMは、設備状態の変化だけを監視して実施時期を決める方式である。","answer":false,"explanation":"時間基準保全は周期・時間を基準にします。"},{"id":1154,"year":2020,"category":"効率化とロス","text":"現場での基本事項として、CBMは、振動や温度など設備状態を基準に保全時期を判断する。","answer":true,"explanation":"状態基準保全は状態監視結果に基づいて保全します。"},{"id":1155,"year":2020,"category":"効率化とロス","text":"現場での基本事項として、改良保全（CM）は、故障した設備を元の状態へ戻すだけで改善は行わない。","answer":false,"explanation":"弱点を改善して信頼性・保全性を向上させる考え方です。"},{"id":1156,"year":2020,"category":"効率化とロス","text":"現場での基本事項として、保全予防（MP）は、新設備の計画・設計段階から保全性を考慮する。","answer":true,"explanation":"MPは保全情報を新設備の計画・設計へ反映します。"},{"id":1157,"year":2020,"category":"効率化とロス","text":"現場での基本事項として、TPMは、保全部門だけが設備を管理し、製造部門は参加しない活動である。","answer":false,"explanation":"TPMは全部門・全員参加が基本です。"},{"id":1158,"year":2020,"category":"効率化とロス","text":"現場での基本事項として、ロスを件数・時間・金額などで定量化すると、改善の優先順位を決めやすい。","answer":true,"explanation":"定量化により重点指向で改善できます。"},{"id":1159,"year":2020,"category":"効率化とロス","text":"現場での基本事項として、TPMでは設備停止だけをロスとし、人や原単位のロスは対象外である。","answer":false,"explanation":"生産システム全体のロスを捉えることが重要です。"},{"id":1160,"year":2020,"category":"効率化とロス","text":"現場での基本事項として、良品率は、投入数に対する良品数の割合として考えることができる。","answer":true,"explanation":"一般に良品数÷投入数で評価します。"},{"id":1161,"year":2020,"category":"改善・解析","text":"現場での基本事項として、パレート図は、2変数の相関関係だけを確認するための図である。","answer":false,"explanation":"パレート図は重要な少数を見つけ、改善の優先順位を決めるのに使います。"},{"id":1162,"year":2020,"category":"改善・解析","text":"現場での基本事項として、特性要因図は、結果に影響する原因候補を体系的に整理するために使う。","answer":true,"explanation":"魚の骨状に要因を整理し、原因探索に活用します。"},{"id":1163,"year":2020,"category":"改善・解析","text":"現場での基本事項として、ヒストグラムは、原因と結果の2変数を点でプロットする図である。","answer":false,"explanation":"区間ごとの度数を棒で表し、分布の形やばらつきを見ます。"},{"id":1164,"year":2020,"category":"改善・解析","text":"現場での基本事項として、散布図は、2種類のデータの関係や相関を確認するのに使う。","answer":true,"explanation":"対応する2変数を点で表し、関係性を確認します。"},{"id":1165,"year":2020,"category":"改善・解析","text":"現場での基本事項として、チェックシートは、必ず複雑な統計計算を自動実行する装置である。","answer":false,"explanation":"現場でデータを取りやすく、集計しやすくする基本ツールです。"},{"id":1166,"year":2020,"category":"改善・解析","text":"現場での基本事項として、管理図は、工程が統計的に安定しているかを時系列で監視するのに使う。","answer":true,"explanation":"管理限界は工程データから設定され、仕様限界とは目的が異なります。"},{"id":1167,"year":2020,"category":"改善・解析","text":"現場での基本事項として、層別では、すべてのデータを区別せず一つにまとめることが目的である。","answer":false,"explanation":"条件ごとに分けることで問題の偏りを見つけやすくなります。"},{"id":1168,"year":2020,"category":"改善・解析","text":"現場での基本事項として、4Mは、Man・Machine・Material・Methodの観点で要因を整理する方法である。","answer":true,"explanation":"4Mは人・設備・材料・方法の視点です。"},{"id":1169,"year":2020,"category":"改善・解析","text":"現場での基本事項として、なぜなぜ分析では、最初に思いついた原因を検証せず真因と決める。","answer":false,"explanation":"事実を確認しながら因果関係を掘り下げます。"},{"id":1170,"year":2020,"category":"改善・解析","text":"現場での基本事項として、QCストーリーでは、現状把握・原因解析・対策・効果確認などの手順で問題解決を進める。","answer":true,"explanation":"問題解決を一定の手順で進め、効果を確認して標準化します。"},{"id":1171,"year":2020,"category":"改善・解析","text":"現場での基本事項として、ECRSのEはExpandで、作業を増やすことを最優先する。","answer":false,"explanation":"ECRSは排除・結合・交換・簡素化の観点です。"},{"id":1172,"year":2020,"category":"改善・解析","text":"現場での基本事項として、ECRSのCはCombineで、別々の作業をまとめられないか検討する。","answer":true,"explanation":"Combineは作業や工程の結合です。"},{"id":1173,"year":2020,"category":"改善・解析","text":"現場での基本事項として、作業改善では、歩行距離や探す時間は生産性に影響しないため無視する。","answer":false,"explanation":"動作・運搬・待ちなどのムダを減らすことが重要です。"},{"id":1174,"year":2020,"category":"改善・解析","text":"現場での基本事項として、改善後は、対策前後のデータを比較して効果を確認する。","answer":true,"explanation":"データで効果を検証し、必要なら追加対策を行います。"},{"id":1175,"year":2020,"category":"改善・解析","text":"現場での基本事項として、改善効果が出たら、手順を標準化せず担当者の記憶だけに任せる。","answer":false,"explanation":"再発防止と横展開には標準化が重要です。"},{"id":1176,"year":2020,"category":"改善・解析","text":"現場での基本事項として、問題解析では、現象と原因を区別して事実に基づき検討する。","answer":true,"explanation":"現地現物とデータに基づいて真因を特定します。"},{"id":1177,"year":2020,"category":"改善・解析","text":"現場での基本事項として、正常・異常の判定は、担当者ごとの感覚だけに任せる方が再現性が高い。","answer":false,"explanation":"定量基準により判断のばらつきを減らせます。"},{"id":1178,"year":2020,"category":"改善・解析","text":"現場での基本事項として、再発防止では、原因に対する恒久対策を行うことが重要である。","answer":true,"explanation":"応急処置と恒久対策を区別し、真因へ対策します。"},{"id":1179,"year":2020,"category":"改善・解析","text":"現場での基本事項として、改善テーマは、効果や緊急度に関係なく必ずランダムに選ぶ。","answer":false,"explanation":"重点指向でテーマを選定すると改善効果を高めやすくなります。"},{"id":1180,"year":2020,"category":"改善・解析","text":"現場での基本事項として、データを取るときは、測定条件や単位をそろえることが比較の前提となる。","answer":true,"explanation":"条件や単位をそろえないと正しい比較ができません。"},{"id":1181,"year":2020,"category":"設備保全の基礎","text":"現場での基本事項として、転がり軸受は、転動体を使用せず油膜だけで軸を支持する軸受である。","answer":false,"explanation":"玉やころなどの転動体を用いるのが転がり軸受です。"},{"id":1182,"year":2020,"category":"設備保全の基礎","text":"現場での基本事項として、Vベルトは、プーリーとの摩擦によって動力を伝達する。","answer":true,"explanation":"Vベルトはプーリーとの摩擦を利用する伝動要素です。"},{"id":1183,"year":2020,"category":"設備保全の基礎","text":"現場での基本事項として、チェーンは、強く張るほど常に寿命が延びるため、たるみ確認は不要である。","answer":false,"explanation":"過大張力も過大なたるみも異常の原因になります。"},{"id":1184,"year":2020,"category":"設備保全の基礎","text":"現場での基本事項として、歯車の異常摩耗や歯欠けは、振動や異音の原因になることがある。","answer":true,"explanation":"歯面損傷はかみ合い異常を生み、振動・騒音につながります。"},{"id":1185,"year":2020,"category":"設備保全の基礎","text":"現場での基本事項として、メカニカルシールは、電気回路の過電流を遮断する装置である。","answer":false,"explanation":"回転機器の軸封に使われる代表的な密封装置です。"},{"id":1186,"year":2020,"category":"設備保全の基礎","text":"現場での基本事項として、レギュレーターは、空気圧回路の圧力を設定値へ調整する機器である。","answer":true,"explanation":"レギュレーターは減圧・圧力調整に使います。"},{"id":1187,"year":2020,"category":"設備保全の基礎","text":"現場での基本事項として、エアフィルターは、空気圧シリンダーの往復速度を電気的に記憶する機器である。","answer":false,"explanation":"異物やドレンの除去に用います。"},{"id":1188,"year":2020,"category":"設備保全の基礎","text":"現場での基本事項として、空気圧シリンダーは、圧縮空気のエネルギーを直線運動へ変換する。","answer":true,"explanation":"圧縮空気を利用してロッドを直線運動させます。"},{"id":1189,"year":2020,"category":"設備保全の基礎","text":"現場での基本事項として、油圧シリンダーは、油の温度だけを測定する計器である。","answer":false,"explanation":"油圧アクチュエーターとして直線運動を発生させます。"},{"id":1190,"year":2020,"category":"設備保全の基礎","text":"現場での基本事項として、密閉された流体に加えた圧力が各方向へ伝わる考え方は、パスカルの原理に関係する。","answer":true,"explanation":"密閉流体の圧力は各方向へ等しく伝わります。"},{"id":1191,"year":2020,"category":"設備保全の基礎","text":"現場での基本事項として、電磁弁は、ボルトの締付トルクを直接測定する工具である。","answer":false,"explanation":"ソレノイドを用いて流路を切り替える弁です。"},{"id":1192,"year":2020,"category":"設備保全の基礎","text":"現場での基本事項として、リミットスイッチは、機械的な接触によって位置や動作端を検出する。","answer":true,"explanation":"レバーやローラーへの接触で位置を検出します。"},{"id":1193,"year":2020,"category":"設備保全の基礎","text":"現場での基本事項として、近接センサーは、必ず対象物へ機械的に接触しないと検出できない。","answer":false,"explanation":"誘導形などは金属を非接触で検出できます。"},{"id":1194,"year":2020,"category":"設備保全の基礎","text":"現場での基本事項として、光電センサーは、光量の変化を利用して物体の有無や位置を検出する。","answer":true,"explanation":"投光・受光の変化で対象物を検出します。"},{"id":1195,"year":2020,"category":"設備保全の基礎","text":"現場での基本事項として、オームの法則では、電流は抵抗を電圧で割って求める。","answer":false,"explanation":"I=V/Rです。"},{"id":1196,"year":2020,"category":"設備保全の基礎","text":"現場での基本事項として、テスターで抵抗を測定するときは、原則として測定対象を無電圧にする。","answer":true,"explanation":"抵抗測定は電源を切り、安全を確認して行います。"},{"id":1197,"year":2020,"category":"設備保全の基礎","text":"現場での基本事項として、インバーターは、低圧配線を機械的に切断するだけの工具である。","answer":false,"explanation":"周波数・電圧制御によりモーター速度を調整します。"},{"id":1198,"year":2020,"category":"設備保全の基礎","text":"現場での基本事項として、ノギスは、外側寸法・内側寸法・深さなどを測定できる。","answer":true,"explanation":"ノギスは寸法測定に使用する測定器です。"},{"id":1199,"year":2020,"category":"設備保全の基礎","text":"現場での基本事項として、マイクロメータは、ノギスより必ず粗い1 mm単位でしか測定できない。","answer":false,"explanation":"マイクロメータは高精度な寸法測定に用います。"},{"id":1200,"year":2020,"category":"設備保全の基礎","text":"現場での基本事項として、寸法公差は、最大許容寸法と最小許容寸法の差である。","answer":true,"explanation":"許容される寸法範囲の幅が寸法公差です。"},{"id":1201,"year":2021,"category":"生産の基本","text":"5Sは、整理・整頓・清掃・清潔・しつけの5項目で構成されるという理解でよい。","answer":true,"explanation":"5Sは整理・整頓・清掃・清潔・しつけです。"},{"id":1202,"year":2021,"category":"生産の基本","text":"整理とは、必要な物を使いやすい場所へ並べる活動だけを指すという理解でよい。","answer":false,"explanation":"不要品を区分して処分するのが整理で、置き場所や置き方を決めるのは整頓です。"},{"id":1203,"year":2021,"category":"生産の基本","text":"整頓では、定位置・定品・定量を決める3定が有効であるという理解でよい。","answer":true,"explanation":"整頓では誰でも分かる置き場所・品目・量を定めることが重要です。"},{"id":1204,"year":2021,"category":"生産の基本","text":"QCDのDは、Designを表すという理解でよい。","answer":false,"explanation":"QCDのDはDelivery（納期）です。"},{"id":1205,"year":2021,"category":"生産の基本","text":"PDCAのCheckでは、実施結果を評価し計画との差を確認するという理解でよい。","answer":true,"explanation":"Checkは結果の確認・評価、Planは計画です。"},{"id":1206,"year":2021,"category":"生産の基本","text":"三現主義は、現場・現金・現役を重視する考え方であるという理解でよい。","answer":false,"explanation":"問題解決では現場へ行き、現物を見て、現実を確認します。"},{"id":1207,"year":2021,"category":"生産の基本","text":"KY活動は、作業前に潜在する危険を予測し、安全行動を決める活動であるという理解でよい。","answer":true,"explanation":"KYは危険予知であり、災害を未然に防ぐために行います。"},{"id":1208,"year":2021,"category":"生産の基本","text":"ヒヤリ・ハットは災害ではないため、記録や共有を行う必要はないという理解でよい。","answer":false,"explanation":"軽微な兆候を共有して危険源を早期に除去することが重要です。"},{"id":1209,"year":2021,"category":"生産の基本","text":"標準作業は、安全・品質・能率を考慮して定めた手順を守ることが基本であるという理解でよい。","answer":true,"explanation":"標準作業はばらつきを抑え、安全・品質・生産性を安定させます。"},{"id":1210,"year":2021,"category":"生産の基本","text":"OJTは、職場を離れて集合研修だけで学ぶ教育方法であるという理解でよい。","answer":false,"explanation":"仕事を通じた教育がOJT、職場を離れた教育はOff-JTです。"},{"id":1211,"year":2021,"category":"生産の基本","text":"Off-JTは、通常業務を離れて研修などで学ぶ教育方法であるという理解でよい。","answer":true,"explanation":"Off-JTは職場業務を離れて行う研修・講習などです。"},{"id":1212,"year":2021,"category":"生産の基本","text":"リスクアセスメントは、生産数量を増やすことだけを目的とするという理解でよい。","answer":false,"explanation":"危険源を特定し、リスク低減措置を検討する安全管理手法です。"},{"id":1213,"year":2021,"category":"生産の基本","text":"フェイルセーフは、機器が故障しても危険側へ移行しにくくする考え方であるという理解でよい。","answer":true,"explanation":"故障時に安全側へ移行する設計思想がフェイルセーフです。"},{"id":1214,"year":2021,"category":"生産の基本","text":"フールプルーフは、熟練者だけが操作できるよう手順を複雑にする考え方であるという理解でよい。","answer":false,"explanation":"人がミスしても危険や不良につながりにくい仕組みにします。"},{"id":1215,"year":2021,"category":"生産の基本","text":"酸素濃度18％未満は、酸素欠乏状態として扱われるという理解でよい。","answer":true,"explanation":"酸素欠乏症等防止規則では18％未満を酸素欠乏とします。"},{"id":1216,"year":2021,"category":"生産の基本","text":"保護具は設備停止中だけ使用し、運転中は着用しないのが原則であるという理解でよい。","answer":false,"explanation":"危険源に応じて適切な保護具を選び、定められた方法で着用します。"},{"id":1217,"year":2021,"category":"生産の基本","text":"抜取り検査は、ロットの一部を抽出して合否判定に用いる検査であるという理解でよい。","answer":true,"explanation":"全数を検査するのは全数検査、ロットの一部を調べるのが抜取り検査です。"},{"id":1218,"year":2021,"category":"生産の基本","text":"環境管理の3Rは、Repair・Return・Recordであるという理解でよい。","answer":false,"explanation":"3Rは発生抑制・再使用・再生利用です。"},{"id":1219,"year":2021,"category":"生産の基本","text":"典型7公害には、大気汚染・水質汚濁・騒音などが含まれるという理解でよい。","answer":true,"explanation":"典型7公害は環境基本法上の公害類型です。"},{"id":1220,"year":2021,"category":"生産の基本","text":"5W1Hの5つのWには、Watch・Write・Work・Wash・Waitが含まれるという理解でよい。","answer":false,"explanation":"5W1Hは誰が、何を、いつ、どこで、なぜ、どのように、で整理します。"},{"id":1221,"year":2021,"category":"設備の日常保全","text":"自主保全の基本条件には、清掃・給油・増し締めが含まれるという理解でよい。","answer":true,"explanation":"清掃・給油・増し締めは設備の基本条件を整える代表的な活動です。"},{"id":1222,"year":2021,"category":"設備の日常保全","text":"清掃は外観をきれいにするだけで、点検とは無関係であるという理解でよい。","answer":false,"explanation":"清掃を通じて漏れ、ゆるみ、摩耗、異音などを発見します。"},{"id":1223,"year":2021,"category":"設備の日常保全","text":"初期清掃では、汚れを除去しながら不具合や不要物を発見するという理解でよい。","answer":true,"explanation":"自主保全の初期段階では清掃を通じて設備の実態を把握します。"},{"id":1224,"year":2021,"category":"設備の日常保全","text":"発生源対策では、汚れの発生量を増やして清掃回数を多くするという理解でよい。","answer":false,"explanation":"清掃だけでなく、汚れを出さない・飛散させない改善が重要です。"},{"id":1225,"year":2021,"category":"設備の日常保全","text":"困難箇所対策では、清掃・点検・給油を短時間かつ安全に行えるよう改善するという理解でよい。","answer":true,"explanation":"点検窓、給油口の集約、カバー改善などで保全性を高めます。"},{"id":1226,"year":2021,"category":"設備の日常保全","text":"暫定基準は、生産数量だけを定める表であり点検内容は含まれないという理解でよい。","answer":false,"explanation":"自主保全基準には対象、方法、周期、判定基準などを明確にします。"},{"id":1227,"year":2021,"category":"設備の日常保全","text":"強制劣化は、清掃・給油・増し締め不足などにより本来防げる劣化が進むことであるという理解でよい。","answer":true,"explanation":"基本条件の不備による人為的な劣化を強制劣化と呼びます。"},{"id":1228,"year":2021,"category":"設備の日常保全","text":"自然劣化は、締付不足や給油忘れだけによって発生するという理解でよい。","answer":false,"explanation":"時間経過による腐食や老化などが自然劣化です。"},{"id":1229,"year":2021,"category":"設備の日常保全","text":"指定と異なる潤滑油を安易に混用すると、性能低下を招く場合があるという理解でよい。","answer":true,"explanation":"油種や添加剤の相性で性能が低下することがあるため、指定油を守ります。"},{"id":1230,"year":2021,"category":"設備の日常保全","text":"潤滑の主目的は、摩擦を増やして機械を停止させることであるという理解でよい。","answer":false,"explanation":"潤滑は摩擦・摩耗低減、冷却、防錆、密封などに寄与します。"},{"id":1231,"year":2021,"category":"設備の日常保全","text":"グリースは、基油に増ちょう剤などを加えた半固体状の潤滑剤であるという理解でよい。","answer":true,"explanation":"グリースは基油を増ちょう剤で保持した潤滑剤です。"},{"id":1232,"year":2021,"category":"設備の日常保全","text":"油面計が汚れて読めなくても、給油してあれば管理上問題ないという理解でよい。","answer":false,"explanation":"油量を見える化し、正常・異常を容易に判定できる状態が必要です。"},{"id":1233,"year":2021,"category":"設備の日常保全","text":"日常点検では、運転中の音・振動・温度・漏れなどを確認することがあるという理解でよい。","answer":true,"explanation":"日常点検は五感や簡易計器による状態確認が中心です。"},{"id":1234,"year":2021,"category":"設備の日常保全","text":"ボルトの合いマークは、締結トルクを自動で増加させる装置であるという理解でよい。","answer":false,"explanation":"マークのずれにより、ゆるみの兆候を視覚的に確認できます。"},{"id":1235,"year":2021,"category":"設備の日常保全","text":"締結部のゆるみは、振動増大や部品脱落の原因になることがあるという理解でよい。","answer":true,"explanation":"ゆるみは振動、騒音、位置ずれ、脱落などにつながります。"},{"id":1236,"year":2021,"category":"設備の日常保全","text":"空気圧設備のフィルタやドレンは、設備寿命に影響しないため点検不要であるという理解でよい。","answer":false,"explanation":"異物や水分は機器の作動不良や腐食につながるため管理が必要です。"},{"id":1237,"year":2021,"category":"設備の日常保全","text":"点検箇所の集中化や見える化は、点検時間短縮と見落とし防止に役立つという理解でよい。","answer":true,"explanation":"アクセス性を高め、正常・異常を判定しやすくする改善が有効です。"},{"id":1238,"year":2021,"category":"設備の日常保全","text":"不具合札は、異常箇所を隠して他の作業者に知らせないために使うという理解でよい。","answer":false,"explanation":"不具合の発見・処置・完了を見える化して管理します。"},{"id":1239,"year":2021,"category":"設備の日常保全","text":"自主保全では、発見した微欠陥を放置せず、復元または改善につなげるという理解でよい。","answer":true,"explanation":"小さな異常を早期に処置することが故障の未然防止につながります。"},{"id":1240,"year":2021,"category":"設備の日常保全","text":"自主保全では、正常・異常の判断基準を個人の勘だけに任せることが望ましいという理解でよい。","answer":false,"explanation":"定量的な判定基準を決め、誰でも同じ判断ができるようにします。"},{"id":1241,"year":2021,"category":"効率化とロス","text":"設備総合効率は、時間稼働率・性能稼働率・良品率の積で表されるという理解でよい。","answer":true,"explanation":"OEEは時間稼働率×性能稼働率×良品率で求めます。"},{"id":1242,"year":2021,"category":"効率化とロス","text":"故障による停止時間が増えるほど、時間稼働率は高くなるという理解でよい。","answer":false,"explanation":"稼働時間が減るため時間稼働率は低下します。"},{"id":1243,"year":2021,"category":"効率化とロス","text":"チョコ停や速度低下は、性能稼働率に影響するという理解でよい。","answer":true,"explanation":"小停止や速度低下は設備の本来性能を発揮できないロスです。"},{"id":1244,"year":2021,"category":"効率化とロス","text":"不良品が増えるほど、良品率は必ず上昇するという理解でよい。","answer":false,"explanation":"投入数に対する良品数の割合が低下します。"},{"id":1245,"year":2021,"category":"効率化とロス","text":"故障ロスは、設備効率を阻害する代表的なロスの一つであるという理解でよい。","answer":true,"explanation":"故障停止は設備の有効稼働時間を減らす大きなロスです。"},{"id":1246,"year":2021,"category":"効率化とロス","text":"段取り時間を長くするほど、時間稼働率が向上するという理解でよい。","answer":false,"explanation":"段取り短縮は停止時間を減らし、稼働時間を増やします。"},{"id":1247,"year":2021,"category":"効率化とロス","text":"チョコ停は、短時間の一時停止や空転が繰り返される現象を指すという理解でよい。","answer":true,"explanation":"短時間でも頻発すると大きな性能ロスになります。"},{"id":1248,"year":2021,"category":"効率化とロス","text":"基準速度より速く運転すれば、どのような場合も速度低下ロスが発生するという理解でよい。","answer":false,"explanation":"本来出せる速度に対して実際の速度が低い差がロスです。"},{"id":1249,"year":2021,"category":"効率化とロス","text":"立上りロスは、始業時や条件変更後に安定生産へ移るまでに生じるという理解でよい。","answer":true,"explanation":"条件安定までの時間や不良発生などを立上りロスとして捉えます。"},{"id":1250,"year":2021,"category":"効率化とロス","text":"機能停止型故障では、設備は常に本来性能を100％維持しているという理解でよい。","answer":false,"explanation":"機能が停止する故障と、性能が低下する機能低下型故障があります。"},{"id":1251,"year":2021,"category":"効率化とロス","text":"予防保全は、故障を未然に防ぐため計画的に保全する考え方であるという理解でよい。","answer":true,"explanation":"故障前に点検・交換などを行うのが予防保全です。"},{"id":1252,"year":2021,"category":"効率化とロス","text":"事後保全は、設備状態を常時監視して故障前に部品交換する方式だけを指すという理解でよい。","answer":false,"explanation":"故障発生後に処置する保全を事後保全と呼びます。"},{"id":1253,"year":2021,"category":"効率化とロス","text":"TBMは、時間や使用回数など一定の周期を基準に行う保全であるという理解でよい。","answer":true,"explanation":"時間基準保全は周期・時間を基準にします。"},{"id":1254,"year":2021,"category":"効率化とロス","text":"CBMは、設備状態に関係なく必ず同じ日付に部品交換する方式であるという理解でよい。","answer":false,"explanation":"状態基準保全は状態監視結果に基づいて保全します。"},{"id":1255,"year":2021,"category":"効率化とロス","text":"改良保全（CM）は、故障しにくく保全しやすい設備へ改善する活動であるという理解でよい。","answer":true,"explanation":"弱点を改善して信頼性・保全性を向上させる考え方です。"},{"id":1256,"year":2021,"category":"効率化とロス","text":"保全予防（MP）は、設備導入後に故障してから設計を考える活動だけを指すという理解でよい。","answer":false,"explanation":"MPは保全情報を新設備の計画・設計へ反映します。"},{"id":1257,"year":2021,"category":"効率化とロス","text":"TPMは、トップから第一線まで全員参加でロスゼロを目指す活動であるという理解でよい。","answer":true,"explanation":"TPMは全部門・全員参加が基本です。"},{"id":1258,"year":2021,"category":"効率化とロス","text":"ロスは数値化せず感覚だけで判断する方が、重点課題を選びやすいという理解でよい。","answer":false,"explanation":"定量化により重点指向で改善できます。"},{"id":1259,"year":2021,"category":"効率化とロス","text":"設備だけでなく、人や材料・エネルギーに関するロスも改善対象となるという理解でよい。","answer":true,"explanation":"生産システム全体のロスを捉えることが重要です。"},{"id":1260,"year":2021,"category":"効率化とロス","text":"良品率は、不良数を良品数で割った値だけを指すという理解でよい。","answer":false,"explanation":"一般に良品数÷投入数で評価します。"},{"id":1261,"year":2021,"category":"改善・解析","text":"パレート図は、項目を大きい順に並べて重点課題を見つけるのに有効であるという理解でよい。","answer":true,"explanation":"パレート図は重要な少数を見つけ、改善の優先順位を決めるのに使います。"},{"id":1262,"year":2021,"category":"改善・解析","text":"特性要因図は、時系列データの管理限界だけを監視する図であるという理解でよい。","answer":false,"explanation":"魚の骨状に要因を整理し、原因探索に活用します。"},{"id":1263,"year":2021,"category":"改善・解析","text":"ヒストグラムは、データの分布やばらつきを把握するのに使うという理解でよい。","answer":true,"explanation":"区間ごとの度数を棒で表し、分布の形やばらつきを見ます。"},{"id":1264,"year":2021,"category":"改善・解析","text":"散布図は、不良項目を大きい順に並べるためだけの図であるという理解でよい。","answer":false,"explanation":"対応する2変数を点で表し、関係性を確認します。"},{"id":1265,"year":2021,"category":"改善・解析","text":"チェックシートは、データを決めた形式で簡単に記録・集計するために使うという理解でよい。","answer":true,"explanation":"現場でデータを取りやすく、集計しやすくする基本ツールです。"},{"id":1266,"year":2021,"category":"改善・解析","text":"管理図の管理限界線は、顧客仕様の上限・下限と常に同じ値であるという理解でよい。","answer":false,"explanation":"管理限界は工程データから設定され、仕様限界とは目的が異なります。"},{"id":1267,"year":2021,"category":"改善・解析","text":"層別は、機械別・人別・材料別などにデータを分けて特徴を調べる考え方であるという理解でよい。","answer":true,"explanation":"条件ごとに分けることで問題の偏りを見つけやすくなります。"},{"id":1268,"year":2021,"category":"改善・解析","text":"4Mは、Money・Market・Month・Memoの4項目を指すという理解でよい。","answer":false,"explanation":"4Mは人・設備・材料・方法の視点です。"},{"id":1269,"year":2021,"category":"改善・解析","text":"なぜなぜ分析では、現象に対して「なぜ」を繰り返して真因へ近づくという理解でよい。","answer":true,"explanation":"事実を確認しながら因果関係を掘り下げます。"},{"id":1270,"year":2021,"category":"改善・解析","text":"QCストーリーでは、原因を調べる前に対策を固定し、効果確認は行わないという理解でよい。","answer":false,"explanation":"問題解決を一定の手順で進め、効果を確認して標準化します。"},{"id":1271,"year":2021,"category":"改善・解析","text":"ECRSのEはEliminateで、不要な作業をなくせないか検討するという理解でよい。","answer":true,"explanation":"ECRSは排除・結合・交換・簡素化の観点です。"},{"id":1272,"year":2021,"category":"改善・解析","text":"ECRSのCはCancelで、設備を停止することだけを意味するという理解でよい。","answer":false,"explanation":"Combineは作業や工程の結合です。"},{"id":1273,"year":2021,"category":"改善・解析","text":"作業改善では、不要な移動や探す時間を減らすことも改善対象となるという理解でよい。","answer":true,"explanation":"動作・運搬・待ちなどのムダを減らすことが重要です。"},{"id":1274,"year":2021,"category":"改善・解析","text":"改善後は、効果確認をせず対策を成功と判断するのが原則であるという理解でよい。","answer":false,"explanation":"データで効果を検証し、必要なら追加対策を行います。"},{"id":1275,"year":2021,"category":"改善・解析","text":"効果が確認できた改善は、標準化して良い状態を維持することが重要であるという理解でよい。","answer":true,"explanation":"再発防止と横展開には標準化が重要です。"},{"id":1276,"year":2021,"category":"改善・解析","text":"問題解析では、原因を確認せず推測だけで対策する方が再発防止に有効であるという理解でよい。","answer":false,"explanation":"現地現物とデータに基づいて真因を特定します。"},{"id":1277,"year":2021,"category":"改善・解析","text":"管理値を設定すると、正常・異常の判定を定量化しやすいという理解でよい。","answer":true,"explanation":"定量基準により判断のばらつきを減らせます。"},{"id":1278,"year":2021,"category":"改善・解析","text":"再発防止では、原因を残したまま応急処置だけを繰り返すことが最適であるという理解でよい。","answer":false,"explanation":"応急処置と恒久対策を区別し、真因へ対策します。"},{"id":1279,"year":2021,"category":"改善・解析","text":"改善テーマは、ロスの大きさや緊急度などを基に優先順位を決めるとよいという理解でよい。","answer":true,"explanation":"重点指向でテーマを選定すると改善効果を高めやすくなります。"},{"id":1280,"year":2021,"category":"改善・解析","text":"測定条件や単位が異なっていても、そのまま比較して問題ないという理解でよい。","answer":false,"explanation":"条件や単位をそろえないと正しい比較ができません。"},{"id":1281,"year":2021,"category":"設備保全の基礎","text":"転がり軸受は、転動体を介して軸を支持する軸受であるという理解でよい。","answer":true,"explanation":"玉やころなどの転動体を用いるのが転がり軸受です。"},{"id":1282,"year":2021,"category":"設備保全の基礎","text":"Vベルトは、歯車のかみ合いだけで動力を伝達するという理解でよい。","answer":false,"explanation":"Vベルトはプーリーとの摩擦を利用する伝動要素です。"},{"id":1283,"year":2021,"category":"設備保全の基礎","text":"チェーン伝動では、張り過ぎだけでなく適正なたるみや給油状態も確認するという理解でよい。","answer":true,"explanation":"過大張力も過大なたるみも異常の原因になります。"},{"id":1284,"year":2021,"category":"設備保全の基礎","text":"歯車の歯が欠けても、回転状態や振動には影響しないという理解でよい。","answer":false,"explanation":"歯面損傷はかみ合い異常を生み、振動・騒音につながります。"},{"id":1285,"year":2021,"category":"設備保全の基礎","text":"メカニカルシールは、回転軸周りの流体漏れを抑える密封装置の一つであるという理解でよい。","answer":true,"explanation":"回転機器の軸封に使われる代表的な密封装置です。"},{"id":1286,"year":2021,"category":"設備保全の基礎","text":"レギュレーターは、圧縮空気中の油分を完全燃焼させる機器であるという理解でよい。","answer":false,"explanation":"レギュレーターは減圧・圧力調整に使います。"},{"id":1287,"year":2021,"category":"設備保全の基礎","text":"エアフィルターは、圧縮空気中の異物や水分を除去するために用いるという理解でよい。","answer":true,"explanation":"異物やドレンの除去に用います。"},{"id":1288,"year":2021,"category":"設備保全の基礎","text":"空気圧シリンダーは、交流電圧を直流へ変換する機器であるという理解でよい。","answer":false,"explanation":"圧縮空気を利用してロッドを直線運動させます。"},{"id":1289,"year":2021,"category":"設備保全の基礎","text":"油圧シリンダーは、油圧エネルギーを直線往復運動に変換するという理解でよい。","answer":true,"explanation":"油圧アクチュエーターとして直線運動を発生させます。"},{"id":1290,"year":2021,"category":"設備保全の基礎","text":"パスカルの原理では、密閉流体に加えた圧力は一方向にしか伝わらないという理解でよい。","answer":false,"explanation":"密閉流体の圧力は各方向へ等しく伝わります。"},{"id":1291,"year":2021,"category":"設備保全の基礎","text":"電磁弁は、電気信号によって流体の流れ方向などを切り替えるために使われるという理解でよい。","answer":true,"explanation":"ソレノイドを用いて流路を切り替える弁です。"},{"id":1292,"year":2021,"category":"設備保全の基礎","text":"リミットスイッチは、主に液体のpHを非接触で測定するセンサーであるという理解でよい。","answer":false,"explanation":"レバーやローラーへの接触で位置を検出します。"},{"id":1293,"year":2021,"category":"設備保全の基礎","text":"近接センサーは、対象物に接触せず検出できる種類があるという理解でよい。","answer":true,"explanation":"誘導形などは金属を非接触で検出できます。"},{"id":1294,"year":2021,"category":"設備保全の基礎","text":"光電センサーは、圧縮空気の圧力だけを測定する機器であるという理解でよい。","answer":false,"explanation":"投光・受光の変化で対象物を検出します。"},{"id":1295,"year":2021,"category":"設備保全の基礎","text":"オームの法則では、電流は電圧を抵抗で割って求められるという理解でよい。","answer":true,"explanation":"I=V/Rです。"},{"id":1296,"year":2021,"category":"設備保全の基礎","text":"テスターで抵抗を測定するときは、必ず通電中の回路へ接続するという理解でよい。","answer":false,"explanation":"抵抗測定は電源を切り、安全を確認して行います。"},{"id":1297,"year":2021,"category":"設備保全の基礎","text":"インバーターは、モーターへ供給する周波数などを制御して回転速度を調整できるという理解でよい。","answer":true,"explanation":"周波数・電圧制御によりモーター速度を調整します。"},{"id":1298,"year":2021,"category":"設備保全の基礎","text":"ノギスは、電圧・電流・抵抗を測定する電気計器であるという理解でよい。","answer":false,"explanation":"ノギスは寸法測定に使用する測定器です。"},{"id":1299,"year":2021,"category":"設備保全の基礎","text":"マイクロメータは、一般にノギスより細かい寸法を読み取れるという理解でよい。","answer":true,"explanation":"マイクロメータは高精度な寸法測定に用います。"},{"id":1300,"year":2021,"category":"設備保全の基礎","text":"寸法公差は、図面寸法と実測値の差だけを指すという理解でよい。","answer":false,"explanation":"許容される寸法範囲の幅が寸法公差です。"},{"id":1301,"year":2022,"category":"生産の基本","text":"基礎事項として、5Sは、整理・整頓・清掃・修理・しつけの5項目で構成される。","answer":false,"explanation":"5Sは整理・整頓・清掃・清潔・しつけです。"},{"id":1302,"year":2022,"category":"生産の基本","text":"基礎事項として、整理とは、必要な物と不要な物を分け、不要な物を処分する活動である。","answer":true,"explanation":"不要品を区分して処分するのが整理で、置き場所や置き方を決めるのは整頓です。"},{"id":1303,"year":2022,"category":"生産の基本","text":"基礎事項として、整頓では、置き場所を決めず、作業者ごとに使いやすい位置へ置くのが基本である。","answer":false,"explanation":"整頓では誰でも分かる置き場所・品目・量を定めることが重要です。"},{"id":1304,"year":2022,"category":"生産の基本","text":"基礎事項として、QCDは、Quality・Cost・Deliveryを表す。","answer":true,"explanation":"QCDのDはDelivery（納期）です。"},{"id":1305,"year":2022,"category":"生産の基本","text":"基礎事項として、PDCAのCheckでは、新しい計画を立てることだけを行う。","answer":false,"explanation":"Checkは結果の確認・評価、Planは計画です。"},{"id":1306,"year":2022,"category":"生産の基本","text":"基礎事項として、三現主義は、現場・現物・現実を重視する考え方である。","answer":true,"explanation":"問題解決では現場へ行き、現物を見て、現実を確認します。"},{"id":1307,"year":2022,"category":"生産の基本","text":"基礎事項として、KY活動は、災害発生後に責任者を決めることを目的とする活動である。","answer":false,"explanation":"KYは危険予知であり、災害を未然に防ぐために行います。"},{"id":1308,"year":2022,"category":"生産の基本","text":"基礎事項として、ヒヤリ・ハット事例の共有は、重大災害の未然防止に役立つ。","answer":true,"explanation":"軽微な兆候を共有して危険源を早期に除去することが重要です。"},{"id":1309,"year":2022,"category":"生産の基本","text":"基礎事項として、標準作業は、作業者が毎回自由に手順を変更することを前提とする。","answer":false,"explanation":"標準作業はばらつきを抑え、安全・品質・生産性を安定させます。"},{"id":1310,"year":2022,"category":"生産の基本","text":"基礎事項として、OJTは、実際の仕事を通じて知識や技能を身につける教育方法である。","answer":true,"explanation":"仕事を通じた教育がOJT、職場を離れた教育はOff-JTです。"},{"id":1311,"year":2022,"category":"生産の基本","text":"基礎事項として、Off-JTは、必ず実機を運転しながら行う教育方法である。","answer":false,"explanation":"Off-JTは職場業務を離れて行う研修・講習などです。"},{"id":1312,"year":2022,"category":"生産の基本","text":"基礎事項として、リスクアセスメントでは、危険性・有害性を特定し、リスクを見積もって低減する。","answer":true,"explanation":"危険源を特定し、リスク低減措置を検討する安全管理手法です。"},{"id":1313,"year":2022,"category":"生産の基本","text":"基礎事項として、フェイルセーフは、故障時に設備を最高速度で運転継続させる考え方である。","answer":false,"explanation":"故障時に安全側へ移行する設計思想がフェイルセーフです。"},{"id":1314,"year":2022,"category":"生産の基本","text":"基礎事項として、フールプルーフは、誤操作しても事故や不良につながりにくくする工夫である。","answer":true,"explanation":"人がミスしても危険や不良につながりにくい仕組みにします。"},{"id":1315,"year":2022,"category":"生産の基本","text":"基礎事項として、酸素濃度20％は、必ず酸素欠乏状態である。","answer":false,"explanation":"酸素欠乏症等防止規則では18％未満を酸素欠乏とします。"},{"id":1316,"year":2022,"category":"生産の基本","text":"基礎事項として、保護メガネや耳栓などの保護具は、対象となる危険に応じて適切に使用する。","answer":true,"explanation":"危険源に応じて適切な保護具を選び、定められた方法で着用します。"},{"id":1317,"year":2022,"category":"生産の基本","text":"基礎事項として、抜取り検査とは、生産した製品をすべて1個ずつ検査することである。","answer":false,"explanation":"全数を検査するのは全数検査、ロットの一部を調べるのが抜取り検査です。"},{"id":1318,"year":2022,"category":"生産の基本","text":"基礎事項として、環境管理の3Rは、Reduce・Reuse・Recycleである。","answer":true,"explanation":"3Rは発生抑制・再使用・再生利用です。"},{"id":1319,"year":2022,"category":"生産の基本","text":"基礎事項として、典型7公害には、納期遅延や在庫過多が含まれる。","answer":false,"explanation":"典型7公害は環境基本法上の公害類型です。"},{"id":1320,"year":2022,"category":"生産の基本","text":"基礎事項として、5W1Hは、Who・What・When・Where・Why・Howで整理する方法である。","answer":true,"explanation":"5W1Hは誰が、何を、いつ、どこで、なぜ、どのように、で整理します。"},{"id":1321,"year":2022,"category":"設備の日常保全","text":"基礎事項として、自主保全の基本条件は、塗装・溶接・機械加工の3項目だけである。","answer":false,"explanation":"清掃・給油・増し締めは設備の基本条件を整える代表的な活動です。"},{"id":1322,"year":2022,"category":"設備の日常保全","text":"基礎事項として、「清掃は点検なり」とは、清掃中に微欠陥や異常を発見することを重視する考え方である。","answer":true,"explanation":"清掃を通じて漏れ、ゆるみ、摩耗、異音などを発見します。"},{"id":1323,"year":2022,"category":"設備の日常保全","text":"基礎事項として、初期清掃では、設備を清掃せずに点検基準書だけを作成する。","answer":false,"explanation":"自主保全の初期段階では清掃を通じて設備の実態を把握します。"},{"id":1324,"year":2022,"category":"設備の日常保全","text":"基礎事項として、発生源対策では、汚れの発生そのものを減らすことを優先する。","answer":true,"explanation":"清掃だけでなく、汚れを出さない・飛散させない改善が重要です。"},{"id":1325,"year":2022,"category":"設備の日常保全","text":"基礎事項として、困難箇所対策では、点検口を減らして設備内部を見えなくする。","answer":false,"explanation":"点検窓、給油口の集約、カバー改善などで保全性を高めます。"},{"id":1326,"year":2022,"category":"設備の日常保全","text":"基礎事項として、暫定基準には、清掃・給油・点検の箇所や周期などを定める。","answer":true,"explanation":"自主保全基準には対象、方法、周期、判定基準などを明確にします。"},{"id":1327,"year":2022,"category":"設備の日常保全","text":"基礎事項として、強制劣化は、設備を正しく管理していても必ず同じ速度で進む自然現象だけを指す。","answer":false,"explanation":"基本条件の不備による人為的な劣化を強制劣化と呼びます。"},{"id":1328,"year":2022,"category":"設備の日常保全","text":"基礎事項として、自然劣化には、経年による腐食や材料の老化などが含まれる。","answer":true,"explanation":"時間経過による腐食や老化などが自然劣化です。"},{"id":1329,"year":2022,"category":"設備の日常保全","text":"基礎事項として、粘度が同じなら、油種や添加剤が異なっても必ず混ぜて使用できる。","answer":false,"explanation":"油種や添加剤の相性で性能が低下することがあるため、指定油を守ります。"},{"id":1330,"year":2022,"category":"設備の日常保全","text":"基礎事項として、潤滑には、摩擦・摩耗の低減や冷却などの役割がある。","answer":true,"explanation":"潤滑は摩擦・摩耗低減、冷却、防錆、密封などに寄与します。"},{"id":1331,"year":2022,"category":"設備の日常保全","text":"基礎事項として、グリースは、潤滑成分を含まない乾燥した粉末だけで構成される。","answer":false,"explanation":"グリースは基油を増ちょう剤で保持した潤滑剤です。"},{"id":1332,"year":2022,"category":"設備の日常保全","text":"基礎事項として、油面計は、油量を正しく確認できるよう清潔で見やすい状態に保つ。","answer":true,"explanation":"油量を見える化し、正常・異常を容易に判定できる状態が必要です。"},{"id":1333,"year":2022,"category":"設備の日常保全","text":"基礎事項として、日常点検では、設備の運転状態を確認せず、必ず全分解して点検する。","answer":false,"explanation":"日常点検は五感や簡易計器による状態確認が中心です。"},{"id":1334,"year":2022,"category":"設備の日常保全","text":"基礎事項として、ボルトの合いマークは、締結部のゆるみを目視で発見しやすくする。","answer":true,"explanation":"マークのずれにより、ゆるみの兆候を視覚的に確認できます。"},{"id":1335,"year":2022,"category":"設備の日常保全","text":"基礎事項として、締結部がゆるむほど、振動は必ず減少し安全性が向上する。","answer":false,"explanation":"ゆるみは振動、騒音、位置ずれ、脱落などにつながります。"},{"id":1336,"year":2022,"category":"設備の日常保全","text":"基礎事項として、空気圧設備では、フィルタの汚れやドレンの滞留も日常点検の対象となる。","answer":true,"explanation":"異物や水分は機器の作動不良や腐食につながるため管理が必要です。"},{"id":1337,"year":2022,"category":"設備の日常保全","text":"基礎事項として、点検箇所を設備の裏側へ分散させるほど、点検は短時間で確実になる。","answer":false,"explanation":"アクセス性を高め、正常・異常を判定しやすくする改善が有効です。"},{"id":1338,"year":2022,"category":"設備の日常保全","text":"基礎事項として、不具合札（エフ）は、発見した異常箇所と処置状況を見える化するために使う。","answer":true,"explanation":"不具合の発見・処置・完了を見える化して管理します。"},{"id":1339,"year":2022,"category":"設備の日常保全","text":"基礎事項として、微欠陥は故障していない限り、記録せず放置するのが原則である。","answer":false,"explanation":"小さな異常を早期に処置することが故障の未然防止につながります。"},{"id":1340,"year":2022,"category":"設備の日常保全","text":"基礎事項として、オペレーターには、正常と異常を判断するための条件設定能力が求められる。","answer":true,"explanation":"定量的な判定基準を決め、誰でも同じ判断ができるようにします。"},{"id":1341,"year":2022,"category":"効率化とロス","text":"基礎事項として、設備総合効率は、時間稼働率と不良率を単純に足して求める。","answer":false,"explanation":"OEEは時間稼働率×性能稼働率×良品率で求めます。"},{"id":1342,"year":2022,"category":"効率化とロス","text":"基礎事項として、故障や段取りによる停止時間は、時間稼働率を低下させる。","answer":true,"explanation":"稼働時間が減るため時間稼働率は低下します。"},{"id":1343,"year":2022,"category":"効率化とロス","text":"基礎事項として、チョコ停や速度低下は、良品率だけに影響し性能稼働率には関係しない。","answer":false,"explanation":"小停止や速度低下は設備の本来性能を発揮できないロスです。"},{"id":1344,"year":2022,"category":"効率化とロス","text":"基礎事項として、不良・手直しが増えると、良品率が低下する。","answer":true,"explanation":"投入数に対する良品数の割合が低下します。"},{"id":1345,"year":2022,"category":"効率化とロス","text":"基礎事項として、故障ロスは、生産効率には影響しないためロスとして扱わない。","answer":false,"explanation":"故障停止は設備の有効稼働時間を減らす大きなロスです。"},{"id":1346,"year":2022,"category":"効率化とロス","text":"基礎事項として、段取り・調整時間の短縮は、停止ロス低減に有効である。","answer":true,"explanation":"段取り短縮は停止時間を減らし、稼働時間を増やします。"},{"id":1347,"year":2022,"category":"効率化とロス","text":"基礎事項として、チョコ停とは、数日間にわたる大規模故障だけを指す。","answer":false,"explanation":"短時間でも頻発すると大きな性能ロスになります。"},{"id":1348,"year":2022,"category":"効率化とロス","text":"基礎事項として、速度低下ロスは、基準速度より遅く運転することで生じる。","answer":true,"explanation":"本来出せる速度に対して実際の速度が低い差がロスです。"},{"id":1349,"year":2022,"category":"効率化とロス","text":"基礎事項として、立上りロスは、設備停止後の廃棄物処理だけを指す。","answer":false,"explanation":"条件安定までの時間や不良発生などを立上りロスとして捉えます。"},{"id":1350,"year":2022,"category":"効率化とロス","text":"基礎事項として、機能停止型故障は、設備が本来の機能を完全に果たせなくなる故障である。","answer":true,"explanation":"機能が停止する故障と、性能が低下する機能低下型故障があります。"},{"id":1351,"year":2022,"category":"効率化とロス","text":"基礎事項として、予防保全は、故障後にだけ修理する事後保全と同じ意味である。","answer":false,"explanation":"故障前に点検・交換などを行うのが予防保全です。"},{"id":1352,"year":2022,"category":"効率化とロス","text":"基礎事項として、事後保全は、故障が発生してから修理・復旧する保全方式である。","answer":true,"explanation":"故障発生後に処置する保全を事後保全と呼びます。"},{"id":1353,"year":2022,"category":"効率化とロス","text":"基礎事項として、TBMは、設備状態の変化だけを監視して実施時期を決める方式である。","answer":false,"explanation":"時間基準保全は周期・時間を基準にします。"},{"id":1354,"year":2022,"category":"効率化とロス","text":"基礎事項として、CBMは、振動や温度など設備状態を基準に保全時期を判断する。","answer":true,"explanation":"状態基準保全は状態監視結果に基づいて保全します。"},{"id":1355,"year":2022,"category":"効率化とロス","text":"基礎事項として、改良保全（CM）は、故障した設備を元の状態へ戻すだけで改善は行わない。","answer":false,"explanation":"弱点を改善して信頼性・保全性を向上させる考え方です。"},{"id":1356,"year":2022,"category":"効率化とロス","text":"基礎事項として、保全予防（MP）は、新設備の計画・設計段階から保全性を考慮する。","answer":true,"explanation":"MPは保全情報を新設備の計画・設計へ反映します。"},{"id":1357,"year":2022,"category":"効率化とロス","text":"基礎事項として、TPMは、保全部門だけが設備を管理し、製造部門は参加しない活動である。","answer":false,"explanation":"TPMは全部門・全員参加が基本です。"},{"id":1358,"year":2022,"category":"効率化とロス","text":"基礎事項として、ロスを件数・時間・金額などで定量化すると、改善の優先順位を決めやすい。","answer":true,"explanation":"定量化により重点指向で改善できます。"},{"id":1359,"year":2022,"category":"効率化とロス","text":"基礎事項として、TPMでは設備停止だけをロスとし、人や原単位のロスは対象外である。","answer":false,"explanation":"生産システム全体のロスを捉えることが重要です。"},{"id":1360,"year":2022,"category":"効率化とロス","text":"基礎事項として、良品率は、投入数に対する良品数の割合として考えることができる。","answer":true,"explanation":"一般に良品数÷投入数で評価します。"},{"id":1361,"year":2022,"category":"改善・解析","text":"基礎事項として、パレート図は、2変数の相関関係だけを確認するための図である。","answer":false,"explanation":"パレート図は重要な少数を見つけ、改善の優先順位を決めるのに使います。"},{"id":1362,"year":2022,"category":"改善・解析","text":"基礎事項として、特性要因図は、結果に影響する原因候補を体系的に整理するために使う。","answer":true,"explanation":"魚の骨状に要因を整理し、原因探索に活用します。"},{"id":1363,"year":2022,"category":"改善・解析","text":"基礎事項として、ヒストグラムは、原因と結果の2変数を点でプロットする図である。","answer":false,"explanation":"区間ごとの度数を棒で表し、分布の形やばらつきを見ます。"},{"id":1364,"year":2022,"category":"改善・解析","text":"基礎事項として、散布図は、2種類のデータの関係や相関を確認するのに使う。","answer":true,"explanation":"対応する2変数を点で表し、関係性を確認します。"},{"id":1365,"year":2022,"category":"改善・解析","text":"基礎事項として、チェックシートは、必ず複雑な統計計算を自動実行する装置である。","answer":false,"explanation":"現場でデータを取りやすく、集計しやすくする基本ツールです。"},{"id":1366,"year":2022,"category":"改善・解析","text":"基礎事項として、管理図は、工程が統計的に安定しているかを時系列で監視するのに使う。","answer":true,"explanation":"管理限界は工程データから設定され、仕様限界とは目的が異なります。"},{"id":1367,"year":2022,"category":"改善・解析","text":"基礎事項として、層別では、すべてのデータを区別せず一つにまとめることが目的である。","answer":false,"explanation":"条件ごとに分けることで問題の偏りを見つけやすくなります。"},{"id":1368,"year":2022,"category":"改善・解析","text":"基礎事項として、4Mは、Man・Machine・Material・Methodの観点で要因を整理する方法である。","answer":true,"explanation":"4Mは人・設備・材料・方法の視点です。"},{"id":1369,"year":2022,"category":"改善・解析","text":"基礎事項として、なぜなぜ分析では、最初に思いついた原因を検証せず真因と決める。","answer":false,"explanation":"事実を確認しながら因果関係を掘り下げます。"},{"id":1370,"year":2022,"category":"改善・解析","text":"基礎事項として、QCストーリーでは、現状把握・原因解析・対策・効果確認などの手順で問題解決を進める。","answer":true,"explanation":"問題解決を一定の手順で進め、効果を確認して標準化します。"},{"id":1371,"year":2022,"category":"改善・解析","text":"基礎事項として、ECRSのEはExpandで、作業を増やすことを最優先する。","answer":false,"explanation":"ECRSは排除・結合・交換・簡素化の観点です。"},{"id":1372,"year":2022,"category":"改善・解析","text":"基礎事項として、ECRSのCはCombineで、別々の作業をまとめられないか検討する。","answer":true,"explanation":"Combineは作業や工程の結合です。"},{"id":1373,"year":2022,"category":"改善・解析","text":"基礎事項として、作業改善では、歩行距離や探す時間は生産性に影響しないため無視する。","answer":false,"explanation":"動作・運搬・待ちなどのムダを減らすことが重要です。"},{"id":1374,"year":2022,"category":"改善・解析","text":"基礎事項として、改善後は、対策前後のデータを比較して効果を確認する。","answer":true,"explanation":"データで効果を検証し、必要なら追加対策を行います。"},{"id":1375,"year":2022,"category":"改善・解析","text":"基礎事項として、改善効果が出たら、手順を標準化せず担当者の記憶だけに任せる。","answer":false,"explanation":"再発防止と横展開には標準化が重要です。"},{"id":1376,"year":2022,"category":"改善・解析","text":"基礎事項として、問題解析では、現象と原因を区別して事実に基づき検討する。","answer":true,"explanation":"現地現物とデータに基づいて真因を特定します。"},{"id":1377,"year":2022,"category":"改善・解析","text":"基礎事項として、正常・異常の判定は、担当者ごとの感覚だけに任せる方が再現性が高い。","answer":false,"explanation":"定量基準により判断のばらつきを減らせます。"},{"id":1378,"year":2022,"category":"改善・解析","text":"基礎事項として、再発防止では、原因に対する恒久対策を行うことが重要である。","answer":true,"explanation":"応急処置と恒久対策を区別し、真因へ対策します。"},{"id":1379,"year":2022,"category":"改善・解析","text":"基礎事項として、改善テーマは、効果や緊急度に関係なく必ずランダムに選ぶ。","answer":false,"explanation":"重点指向でテーマを選定すると改善効果を高めやすくなります。"},{"id":1380,"year":2022,"category":"改善・解析","text":"基礎事項として、データを取るときは、測定条件や単位をそろえることが比較の前提となる。","answer":true,"explanation":"条件や単位をそろえないと正しい比較ができません。"},{"id":1381,"year":2022,"category":"設備保全の基礎","text":"基礎事項として、転がり軸受は、転動体を使用せず油膜だけで軸を支持する軸受である。","answer":false,"explanation":"玉やころなどの転動体を用いるのが転がり軸受です。"},{"id":1382,"year":2022,"category":"設備保全の基礎","text":"基礎事項として、Vベルトは、プーリーとの摩擦によって動力を伝達する。","answer":true,"explanation":"Vベルトはプーリーとの摩擦を利用する伝動要素です。"},{"id":1383,"year":2022,"category":"設備保全の基礎","text":"基礎事項として、チェーンは、強く張るほど常に寿命が延びるため、たるみ確認は不要である。","answer":false,"explanation":"過大張力も過大なたるみも異常の原因になります。"},{"id":1384,"year":2022,"category":"設備保全の基礎","text":"基礎事項として、歯車の異常摩耗や歯欠けは、振動や異音の原因になることがある。","answer":true,"explanation":"歯面損傷はかみ合い異常を生み、振動・騒音につながります。"},{"id":1385,"year":2022,"category":"設備保全の基礎","text":"基礎事項として、メカニカルシールは、電気回路の過電流を遮断する装置である。","answer":false,"explanation":"回転機器の軸封に使われる代表的な密封装置です。"},{"id":1386,"year":2022,"category":"設備保全の基礎","text":"基礎事項として、レギュレーターは、空気圧回路の圧力を設定値へ調整する機器である。","answer":true,"explanation":"レギュレーターは減圧・圧力調整に使います。"},{"id":1387,"year":2022,"category":"設備保全の基礎","text":"基礎事項として、エアフィルターは、空気圧シリンダーの往復速度を電気的に記憶する機器である。","answer":false,"explanation":"異物やドレンの除去に用います。"},{"id":1388,"year":2022,"category":"設備保全の基礎","text":"基礎事項として、空気圧シリンダーは、圧縮空気のエネルギーを直線運動へ変換する。","answer":true,"explanation":"圧縮空気を利用してロッドを直線運動させます。"},{"id":1389,"year":2022,"category":"設備保全の基礎","text":"基礎事項として、油圧シリンダーは、油の温度だけを測定する計器である。","answer":false,"explanation":"油圧アクチュエーターとして直線運動を発生させます。"},{"id":1390,"year":2022,"category":"設備保全の基礎","text":"基礎事項として、密閉された流体に加えた圧力が各方向へ伝わる考え方は、パスカルの原理に関係する。","answer":true,"explanation":"密閉流体の圧力は各方向へ等しく伝わります。"},{"id":1391,"year":2022,"category":"設備保全の基礎","text":"基礎事項として、電磁弁は、ボルトの締付トルクを直接測定する工具である。","answer":false,"explanation":"ソレノイドを用いて流路を切り替える弁です。"},{"id":1392,"year":2022,"category":"設備保全の基礎","text":"基礎事項として、リミットスイッチは、機械的な接触によって位置や動作端を検出する。","answer":true,"explanation":"レバーやローラーへの接触で位置を検出します。"},{"id":1393,"year":2022,"category":"設備保全の基礎","text":"基礎事項として、近接センサーは、必ず対象物へ機械的に接触しないと検出できない。","answer":false,"explanation":"誘導形などは金属を非接触で検出できます。"},{"id":1394,"year":2022,"category":"設備保全の基礎","text":"基礎事項として、光電センサーは、光量の変化を利用して物体の有無や位置を検出する。","answer":true,"explanation":"投光・受光の変化で対象物を検出します。"},{"id":1395,"year":2022,"category":"設備保全の基礎","text":"基礎事項として、オームの法則では、電流は抵抗を電圧で割って求める。","answer":false,"explanation":"I=V/Rです。"},{"id":1396,"year":2022,"category":"設備保全の基礎","text":"基礎事項として、テスターで抵抗を測定するときは、原則として測定対象を無電圧にする。","answer":true,"explanation":"抵抗測定は電源を切り、安全を確認して行います。"},{"id":1397,"year":2022,"category":"設備保全の基礎","text":"基礎事項として、インバーターは、低圧配線を機械的に切断するだけの工具である。","answer":false,"explanation":"周波数・電圧制御によりモーター速度を調整します。"},{"id":1398,"year":2022,"category":"設備保全の基礎","text":"基礎事項として、ノギスは、外側寸法・内側寸法・深さなどを測定できる。","answer":true,"explanation":"ノギスは寸法測定に使用する測定器です。"},{"id":1399,"year":2022,"category":"設備保全の基礎","text":"基礎事項として、マイクロメータは、ノギスより必ず粗い1 mm単位でしか測定できない。","answer":false,"explanation":"マイクロメータは高精度な寸法測定に用います。"},{"id":1400,"year":2022,"category":"設備保全の基礎","text":"基礎事項として、寸法公差は、最大許容寸法と最小許容寸法の差である。","answer":true,"explanation":"許容される寸法範囲の幅が寸法公差です。"}];
